//!src/gateway/openclaw-id/stale-seq.ts
function isStaleSeqRefusal(e,t){return e.payload.kind===`root_statement`&&t.code===`seq_conflict`}async function handleStaleSeqRefusal(e){e.log.info(`openclaw-id: root statement refused for a stale seq (current ${e.currentSeq}); republishing`);await e.republish();const t=e.message.from.device_fp;if(!isKeyFingerprint(t))return;const n=await e.target();if(!n)return;try{await n.client.sendDeviceNotice(n.clawId,t,{kind:`notice`,event:`seq_conflict`,ref:String(e.currentSeq)});e.log.info(`openclaw-id: told ${t} its statement used a stale seq`)}catch(t){e.log.warn(`openclaw-id: could not mail the seq_conflict notice: ${t instanceof Error?t.message:String(t)}`)}}export{handleStaleSeqRefusal,isStaleSeqRefusal};